-- Bootstrap 2 (tracker C7). Objects created by hand on the hosted production database and needed from 20261001210000_learning_loop_rpcs.sql on.
-- Each is created ONLY IF MISSING: on production nothing changes; on an empty database this supplies them. Generated by scripts/release/build_bootstrap.py.
begin;
set local check_function_bodies = off;

do $boot$ begin if to_regprocedure('public.qb_current_teacher_id()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_current_teacher_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select tp.id
    from public.teacher_profiles tp
    where tp.user_id = auth.uid()
    limit 1;
$function$
$qb_bootstrap$; end if; end $boot$;

commit;
